('ectoplasmic-cocoon-mass','Ectoplasmic Cocoon, Mass','metacreativity',NULL,'1 standard action','standard','Medium (100 ft. + 10 ft./level)',NULL,'20-ft.-radius burst',NULL,'1 hour/level (D)','ref','Reflex negates','no',NULL,13,'Cocoon multiple creatures or a sufficiently large single target in a mass of ectoplasm.','For every 2 additional PP, increase burst radius by 5 feet.'),
('ectoplasmic-form','Ectoplasmic Form','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 min./level (D)',NULL,NULL,'no',NULL,5,'Become partially translucent ectoplasm, gaining DR, immunity to poison and critical hits, limited flight, and unusual movement while losing normal physical attacks.',NULL),
('ectoplasmic-shambler','Ectoplasmic Shambler','metacreativity','creation','1 round','full_round','Long (400 ft. + 40 ft./level)',NULL,NULL,'One ectoplasmic manifestation equal to ten 10-ft. cubes (S)','1 min./level',NULL,'None','no',NULL,9,'Create and direct a slow, many-legged ectoplasmic mass that obscures vision, damages enveloped creatures, and disrupts manifestation/casting.',NULL),
