('elfsight','Elfsight','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 hour/level',NULL,NULL,'no',NULL,1,'Gain low-light vision, bonuses on Search and Spot, and passive chances to notice secret or concealed doors.',NULL),
('empathic-feedback','Empathic Feedback','telepathy',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'10 min./level',NULL,NULL,'no',NULL,5,'Melee attackers take empathic damage equal to the damage they dealt you or 5 points, whichever is less.','Each additional PP raises the maximum feedback damage by 1.'),
('empathic-transfer','Empathic Transfer','psychometabolism',NULL,'1 standard action','standard','Touch','Willing creature touched',NULL,NULL,'Instantaneous',NULL,NULL,'no',NULL,3,'Heal another creature by transferring half the healed damage to yourself, or transfer poison, disease, or ability damage onto yourself.','Each additional PP can add another 2d10 healing, to the stated maximum.'),
('empathic-transfer-hostile','Empathic Transfer, Hostile','telepathy',NULL,'1 standard action','standard','Touch','Creature touched',NULL,NULL,'Instantaneous','will','Will half','yes',NULL,5,'Transfer up to 50 points of your damage to a touched creature and heal yourself by the amount transferred.','Additional PP increase transferable damage; a larger augmentation changes the effect to an area around you.'),
('empathy','Empathy','telepathy',NULL,'1 standard action','standard','30 ft.',NULL,'30-ft.-radius spread centered on you',NULL,'Concentration, up to 1 min./level (D)',NULL,'None','no',NULL,1,'Sense surface emotions and gain a short-lived insight bonus on social interaction checks when concentration ends.','Additional PP increase range/radius; 2 additional PP can extend maximum duration to 1 hour/level.'),
('empty-mind','Empty Mind','telepathy',NULL,'1 immediate action','immediate','Personal','You',NULL,NULL,'1 round',NULL,NULL,'no',NULL,1,'Immediately gain a +2 bonus on Will saves until your next action.','For every 2 additional PP, increase the Will-save bonus by 1.'),
('energy-adaptation','Energy Adaptation','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'10 min./level',NULL,NULL,'no',NULL,7,'Gain scaling resistance against acid, cold, electricity, fire, or sonic damage, chosen as attacks occur.','Spend 4 additional PP to manifest as an immediate action.'),
('energy-adaptation-specified','Energy Adaptation, Specified','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'10 min./level',NULL,NULL,'no',NULL,3,'As energy adaptation, but choose a single energy type when manifested.','Spend 4 additional PP to manifest as an immediate action.'),
('energy-ball','Energy Ball','psychokinesis',NULL,'1 standard action','standard','Long (400 ft. + 40 ft./level)',NULL,'20-ft.-radius spread',NULL,'Instantaneous','ref','Reflex half or Fortitude half; see text','yes',NULL,7,'Create a 7d6 burst of cold, electricity, fire, or sonic energy with type-specific modifiers.','Each additional PP adds one damage die; every two extra dice increase save DC by 1.'),
