('energy-conversion','Energy Conversion','psychometabolism',NULL,'1 standard action','standard','Personal and close; see text','You',NULL,'Ray; see text','10 min./level',NULL,'None','yes',NULL,13,'Absorb energy as energy adaptation and store it for later discharge as one or more ranged touch attack rays.',NULL),
('energy-current','Energy Current','psychokinesis',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','Two creatures no more than 15 ft. apart',NULL,NULL,'Concentration, up to 1 round/level','ref','Reflex half or Fortitude half; see text','yes',NULL,9,'Sustain an arc of chosen energy dealing 9d6 each round to a primary target and half damage to a secondary target.','Additional PP increase damage/save DC and can add secondary targets.'),
('energy-missile','Energy Missile','psychokinesis',NULL,'1 standard action','standard','Medium (100 ft. + 10 ft./level)','Up to five creatures or objects, no two more than 15 ft. apart',NULL,NULL,'Instantaneous','ref','Reflex half or Fortitude half; see text','yes',NULL,3,'Strike up to five targets with 3d6 chosen energy damage each.','Each additional PP adds one damage die and increases save DC by 1.'),
('energy-push','Energy Push','psychokinesis',NULL,'1 standard action','standard','Medium (100 ft. + 10 ft./level)',NULL,NULL,'Ray','Instantaneous','ref','Reflex half or Fortitude half; see text','yes',NULL,3,'Deal chosen energy damage and potentially push the target backward, causing collision damage when movement is blocked.','For every 2 additional PP, increase both blast and impact damage by one die and save DC by 1.'),
('energy-ray','Energy Ray','psychokinesis',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'Ray','Instantaneous',NULL,'None','yes',NULL,1,'Make a ranged touch attack dealing 1d6 chosen cold, electricity, fire, or sonic damage with type-specific effects.','Each additional PP adds one damage die.'),
